head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf90009";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — zipList

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf90009.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "txt_p8", fn: function(){ return ((String(((dma_pageContext.get("zipList") ?? "")) == null ? '' : ((dma_pageContext.get("zipList") ?? ""))).length === 0)); } }, { id: "if_zipList_2", fn: function(){ return (!(String(((dma_pageContext.get("zipList") ?? "")) == null ? '' : ((dma_pageContext.get("zipList") ?? ""))).length === 0) && (((dma_pageContext.get("zipList") ?? "")) && typeof ((dma_pageContext.get("zipList") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("zipList") ?? "")).getRowCount() : ((((dma_pageContext.get("zipList") ?? "")) == null) ? 0 : (((dma_pageContext.get("zipList") ?? "")).length || 0))) > 0); } }, { id: "txt_p24", fn: function(){ return (!(String(((dma_pageContext.get("zipList") ?? "")) == null ? '' : ((dma_pageContext.get("zipList") ?? ""))).length === 0) && (((dma_pageContext.get("zipList") ?? "")) && typeof ((dma_pageContext.get("zipList") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("zipList") ?? "")).getRowCount() : ((((dma_pageContext.get("zipList") ?? "")) == null) ? 0 : (((dma_pageContext.get("zipList") ?? "")).length || 0))) === 0); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(roadziplist vs popup_zipcode.jsp vs ziplist) — 어느 쪽인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_zipList_oncellclick
 * @description grd_zipList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_zipList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_zipList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_zipList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.setZipCode(r["zipCode"], r["address"], r["engAddress"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_zipList.oncellclick' });
    }
};

/**
 * @method
 * @name btn_sddSearchZip_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_sddSearchZip_onclick = function () {
    try {
        const kw = ($c.util.getComponent('ibx_sddSearchKeyword') || { getValue: function () { return ''; } }).getValue().trim();
        const o = {};
        ['searchType', 'searchWord', 'searchBldgNo', 'searchBldgNm'].forEach(function (fd) { try { const c = $c.util.getComponent(fd); if (c && c.getValue) { o[fd] = c.getValue(); } } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jldinf90009' }); } });
        o.searchWord = kw;
        $c.win.setPageFrameSrc($c.win.getFrame(), '/jldinf90009/jldinf90009.xml', o);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf90009.btn_sddSearchZip_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setZipCode
 * @description set Zip Code 처리
 * @param {*} zipCode zipCode
 * @param {*} address address
 * @param {*} engAddress engAddress
 * @returns {void}
 * @hidden N
 */
scwin.setZipCode = function (zipCode, address, engAddress) {
    (((scwin.openerScwin()) !== scwin && typeof (scwin.openerScwin()).setZipCode === 'function' ? (scwin.openerScwin()).setZipCode(zipCode, address, engAddress) : void 0), $c.win.closePopup([zipCode, address, engAddress]));
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
